      <MemoryRouter>
        {/* Roughly a real card's own width, matching zimmProductCardMedia/content's own story
            decorators so this reads naturally as the full assembled card. */}
        <Box width="320px">
          <Story />
        </Box>
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductCard>;

/**
 * Wraps `ZimmProductCard` so `selectedSizeChipValue` is genuinely live rather than a static arg —
 * neither `ZimmProductCard` nor the `ZimmSizeChipGroup` it composes tracks selection itself (both
 * are correctly controlled components), so any story that wants a chip click to visually select
 * must own that state itself, the same pattern zimmSizeChipGroup/index.stories.tsx's
 * `KeyboardNavigation` story already uses via its own `KeyboardNavigationExample`. Shared by
 * every enabled-size-chip story in this file rather than each retyping it. Every arg passes
 * straight through unchanged; only
 * `selectedSizeChipValue`/`onSizeChipSelect` become live. `onSizeChipSelectFromArgs` still fires
 * the original `args.onSizeChipSelect` (each story's own `fn()` spy) so Storybook's Actions panel
 * keeps logging the click.
 *
 * `onSizeChipSelect`/`selectedSizeChipValue` only exist on the `plp`/`wishlist` members of
 * `ZimmProductCardProps`'s discriminated union (see zimmProductCard/index.tsx) — `home` has
 * neither. Narrowing via the `variation` discriminant into a single `propsWithLiveSelection`
 * value (rather than spreading `args` and adding those two as separate attributes) matters for
 * real, not just style: once
 * narrowed, `{...args, selectedSizeChipValue, onSizeChipSelect}` is a proper subtype of the
 * `plp`/`wishlist` branch and assigns cleanly to the wider union; attaching the same two
 * attributes directly on top of an unnarrowed `{...args}` spread does NOT — TypeScript distributes
 * that spread per union branch and rejects them on the `home` branch, unlike the lenient "excess
 * property on any one member" behaviour `index.test.tsx` documents for a plain object-literal
 * assignment (confirmed the hard way in this component's original `DefaultExample` draft: `npx
 * tsc --noEmit` correctly rejected it).
 */
const LiveSizeSelectionCard = (args: ZimmProductCardProps) => {
  // Lazy initializer: seeds from args.selectedSizeChipValue once on mount only, never re-syncs on rerender.
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>(() =>
    args.variation === 'plp' || args.variation === 'wishlist' ? args.selectedSizeChipValue : undefined,
  );
  const isSizeChipVariation = args.variation === 'plp' || args.variation === 'wishlist';
  const onSizeChipSelectFromArgs = isSizeChipVariation ? args.onSizeChipSelect : undefined;
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    onSizeChipSelectFromArgs?.(value);
  };
  const propsWithLiveSelection: ZimmProductCardProps = isSizeChipVariation
    ? { ...args, selectedSizeChipValue, onSizeChipSelect: handleSizeChipSelect }
    : args;
  return <ZimmProductCard {...propsWithLiveSelection} />;
};

/**
 * PLP-shaped baseline — also this file's mandatory `Default` export (per
 * .claude/rules/components.md's Storybook conventions), so there is no separately-named `PLP`
 * story: it would have been byte-identical args to this one. Image, name, always-visible bag,
 * price. Hover to check: price hides and the size-chip picker takes its place, arrows appear
 * (multi-image cards only) — Storybook's test runner cannot force a `(hover: hover)` media
 * context, so this is a manual visual check, the same limitation
 * zimmProductCardMedia/index.stories.tsx's `MultipleImages` story documents. No `play` function
 * for the same reason. Also carries the merchandiser `badge` label, top-left of the image —
 * confirmed shown on PLP by SFCC-236's own real AC (`customfield_10231`), not just Dani Rivett's
 * scope note.
 *
 * Resize below the tablet breakpoint to also check Fix D: the bag icon is hidden unconditionally
 * on mobile PLP, regardless of stock status — unlike Wishlist, where the same hide is conditional
 * on being unavailable (see `WishlistOutOfStock` below). Live-verified at a real 375px viewport
 * (2026-09-04): `[data-card-slot="bag"]` computed `display: none`.
 *
 * Size chips are genuinely interactive here, not a static snapshot — starts with nothing selected;
 * click a chip to see it visually select. Rendered via `LiveSizeSelectionCard` above, which owns
 * `selectedSizeChipValue` as local state; every other arg below is unchanged.
 *
 * Figma nodes: Default `40002163:41441` · Hover `40002163:41459` · Mobile `40002163:41477`.
 */
export const Default: Story = {
  args: {
    id: 'prod-1',
    variation: 'plp',
    name: 'Natura Long Sleeve Linen Mini Dress',
    headingLevel: 'h3',
    href: '/product/123',
    primaryImage: PRIMARY_IMAGE,
    hoverImage: HOVER_IMAGE,
    currentPrice: '$595.00',
    badge: 'Runway',
    onAddToBag: fn(),
    sizeChipValues: SIZES,
    onSizeChipSelect: fn(),
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * Out-of-stock PLP: the bag renders disabled and the "Notify me" CTA appears beneath the price.
 * Hover to confirm the size-selector swap still behaves exactly like the in-stock PLP card above
 * (`Default`) — unlike `HomeOutOfStock` below, where price stays visible alongside notify-me
 * rather than being replaced (see index.tsx's own Fix F docblock note for why PLP/Wishlist and
 * Home genuinely differ here).
 *
 * Resize below the tablet breakpoint to also check Fix D (bag unconditionally hidden, same as
 * `Default` above) AND Fix F (mobile-only): unlike desktop's additive treatment (price stays,
 * notify-me simply added), mobile PLP/Wishlist Unavailable genuinely SWAPS price for notify-me.
 * Live-verified at a real 375px viewport (2026-09-04): bag `display: none`, price
 * `display: none`, notify-me `display: block`.
 *
 * Figma nodes: Default `40002163:41450` · Hover `40002163:41468` · Mobile `40002163:41486`.
 */
export const PLPOutOfStock: Story = {
  args: {
    ...Default.args,
    variation: 'plp',
    isUnavailable: true,
    onNotifyMe: fn(),
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * Home card: image + name only by default — no bag, no attributes, no size chips at all. Hover
 * the card to reveal the price, the one variation where price is hidden until hover rather than
 * visible-by-default. Manual visual check only, same Storybook hover-media-context limitation as
 * the `Default` (PLP) card above. Resize below the tablet breakpoint to also check Fix E
 * (full-sweep follow-up visual audit): price must stay visible unconditionally on mobile, since
 * Mobile has no Hover variant at all to ever reveal a price hidden "by default, shown on hover"
 * the way this card's own hover-reveal is expressed for hover-capable pointers.
 *
 * Deliberately passes `badge` too, even though nothing here renders it — proves
 * `VARIATION_CONFIG.showBadge` actually suppresses it for Home rather than this story simply
 * never having supplied one. Compare against `Default`/`Wishlist`, which pass the identical prop
 * and do render it.
 *
 * Also deliberately passes `hoverImage`, for the same reason: hovering must reveal the price
 * only, with no image crossfade to the model photo — `VARIATION_CONFIG.showHoverImageSwap`
 * suppresses that swap for Home. Confirmed by SFCC-236's own real AC (`customfield_10231`): Home's
 * AC list mentions only arrows + price on hover, never an image swap, for every variation but
 * Home. `Default`/`Wishlist` pass the same kind of prop and do swap on hover.
 *
 * Figma nodes: Default `40000214:6141` · Hover `40002163:36593` · Mobile `40000223:2821`.
 */
export const Home: Story = {
  args: {
    id: 'prod-2',
    variation: 'home',
    name: 'Natura Long Sleeve Linen Mini Dress',
    headingLevel: 'h3',
    href: '/product/123',
    primaryImage: PRIMARY_IMAGE,
    hoverImage: HOVER_IMAGE,
    currentPrice: '$595.00',
    badge: 'Runway',
  },
};

/**
 * Out-of-stock Home (Fix F, full-sweep follow-up visual audit): unlike `PLPOutOfStock`/
 * `WishlistOutOfStock` below, Home does NOT swap price for "Notify me" — it keeps its own normal
 * hover-reveals-price behaviour and simply adds notify-me alongside it once both are visible.
 * Confirmed via Figma's Home Unavailable references: Desktop Default (`40002163:39981`) shows
 * name only (no notify-me — nothing has revealed it yet); Desktop Hover (`40002163:39990`) shows
 * price AND notify-me together; Mobile (`40002163:39999`, Card-content `40002163:41204`) shows
 * both permanently, since Mobile has no Hover variant to gate either one. Hover this card (and
 * resize below the tablet breakpoint) to check all three states. Live-verified at a real 375px
 * viewport (2026-09-04): price `display: block`, notify-me `display: block` — both present
 * together, confirming this is additive, not the genuine swap `PLPOutOfStock`/
 * `WishlistOutOfStock` demonstrate.
 */
export const HomeOutOfStock: Story = {
  args: {
    ...Home.args,
    isUnavailable: true,
    onNotifyMe: fn(),
  },
};

/**
 * Wishlist card: colour/size attributes and bag are always visible, plus the remove ('x') overlay
 * on the image. Hover to confirm price swaps out for the size-selector — confirmed identical to
 * PLP's own hover reveal via Figma node `40002187:58460`. SFCC-236's own real AC
 * (`customfield_10231`) for Wishlist lists only the image swap + arrows on hover — this
 * size-selector reveal is design-only, not AC-stated, so it's worth an explicit second look by
 * whoever eyeballs this story. Also carries the merchandiser `badge` label — confirmed shown on
 * Wishlist by that same AC.
 *
 * Mobile: bag stays visible at every breakpoint while in stock (contrast `WishlistOutOfStock`
 * below, where it hides once unavailable). Live-verified at a real 375px viewport (2026-09-04):
 * `[data-card-slot="bag"]` computed `display: flex`.
 *
 * Figma nodes: Default `40002187:58446` · Hover `40002187:58458` · Mobile `40002187:58470`.
 */
export const Wishlist: Story = {
  args: {
    id: 'prod-3',
    variation: 'wishlist',
    name: 'Natura Long Sleeve Linen Mini Dress',
    headingLevel: 'h3',
    href: '/product/123',
    primaryImage: PRIMARY_IMAGE,
    hoverImage: HOVER_IMAGE,
    currentPrice: '$595.00',
    badge: 'Runway',
    colour: 'Ivory',
    size: 'M',
    onRemove: fn(),
    onAddToBag: fn(),
    // Previously omitted entirely, which left the hover-revealed size-chip wrapper empty (no
    // radiogroup rendered) — confirmed live during the SFCC-236 Step 6 visual audit: Wishlist's
    // hover-reveal is otherwise identical to PLP's (see the module docblock), so it needs the
    // same fixture data to actually demonstrate that behaviour. `selectedSizeChipValue: 'm'`
    // matches this story's own `size: 'M'` attribute above, and mirrors Figma's own Wishlist
    // Hover reference (node 40002187:58458), which likewise shows one chip pre-selected.
    sizeChipValues: SIZES,
    selectedSizeChipValue: 'm',
    onSizeChipSelect: fn(),
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * Out-of-stock Wishlist: bag renders disabled and "Notify me" appears, same as PLPOutOfStock —
 * but also demonstrates Fix G (full-sweep follow-up visual audit), Wishlist's own narrower
 * mobile-only bag hide. Resize the preview below the tablet breakpoint to check: unlike the
 * in-stock Wishlist story above (bag stays visible on every breakpoint) and unlike PLP (bag is
 * always mobile-hidden regardless of stock status), THIS card's bag only disappears on mobile
 * once it's unavailable — confirmed via Figma's Mobile Wishlist Unavailable reference
 * (`40002187:58473`, `Icons` frame `hidden="true"`) against the in-stock Mobile Wishlist reference
 * (`40002187:58470`, bag visible).
 *
 * Live-verified at a real 375px viewport (2026-09-04): bag `display: none`, price
 * `display: none`, notify-me `display: block` — the same Fix F genuine swap `PLPOutOfStock`
 * demonstrates applies here too, not just the narrower Fix G bag rule.
 *
 * Figma nodes: Default `40002187:58452` · Hover `40002187:58464` · Mobile `40002187:58473`
 * (contrast in-stock Mobile `40002187:58470` on `Wishlist` above).
 */
export const WishlistOutOfStock: Story = {
  args: {
    ...Wishlist.args,
    isUnavailable: true,
    onNotifyMe: fn(),
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/** Explicit single-image case — no arrows, no indicator, no horizontal overflow, even with a
 *  multi-image-capable variation. Matches zimmProductCardMedia's own SingleImage story. */
export const SingleImage: Story = {
  args: {
    ...Default.args,
    hoverImage: undefined,
    images: undefined,
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * A full multi-image gallery — desktop shows prev/next arrows, touch shows the slide indicator.
 * Hover to see the arrows appear alongside the price/size-selector swap happening at the same
 * time. No `play`: same Storybook hover-media-context limitation as every hover-dependent story
 * above.
 *
 * Fix H (2026-09-05): hover-out now correctly hides the arrows again too (`:has(:focus-visible)`,
 * not the old `:focus-within` which stuck open once a clicked arrow button kept real DOM focus)
 * — part of the same manual hover check above, no `play` function added for it (see `index.tsx`'s
 * own docblock point 6/Fix H for the full mechanism).
 *
 * The slide indicator mentioned above is gated by pointer capability
 * (`(hover: hover) and (pointer: fine)`), not viewport width — plain browser resize won't reveal
 * it; see `zimmProductCardMedia/index.stories.tsx`'s own `MultipleImages` docblock for how to
 * actually verify it (DevTools device/touch emulation) and the accepted trackpad-equipped-tablet
 * consequence of that choice.
 */
export const MultipleImages: Story = {
  args: {
    ...Default.args,
    hoverImage: undefined,
    images: GALLERY_IMAGES,
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * Was/Now (sale) pricing (PRC-09): `originalPrice` set alongside `currentPrice` switches
 * ZimmProductCardContent → ZimmProductPrice to the "Was {X} Now {Y}" treatment (Figma node
 * 40001028:9179). Generic, variation-agnostic atom behaviour — the price atom has no
 * `variation` awareness at all — so demonstrated once here, off the same PLP baseline as
 * `Default`, not once per variation. Prices match zimmProductCardContent/index.stories.tsx's
 * own `WithSalePrice` exactly, so the two layers read as the same fixture product.
 *
 * The was-price uses --zimm-color-text-muted (#969696), 2.95:1 on white — intentionally below
 * 4.5:1 AA to match the Figma design token (alias/color/text/subtlest), the same already-accepted
 * FE-lead call this exact composed treatment inherits from ZimmProductPrice's own OnSale story
 * (see zimmProductPrice.css.ts's `sale.wasPrice` comment and zimmProductCardContent's own
 * WithSalePrice story for the full rationale). `test: 'off'` mirrors that same established
 * suppression here — this story renders the identical composed treatment, not a new one.
 */
export const WithSalePrice: Story = {
  name: 'With sale price (Was/Now, PRC-09)',
  parameters: {
    a11y: { test: 'off' },
  },
  args: {
    ...Default.args,
    currentPrice: '$416.50',
    originalPrice: '$595.00',
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

/**
 * One size offered: ZimmSizeChipGroup's `values.length === 1` branch renders a single
 * non-interactive `<span>` (Figma node 40003066:34866), not a one-item radiogroup — see that
 * component's own `OneSize` story and zimmProductCardContent's own `WithSizeChipsOneSize` for
 * the same branch at the other two composed layers. Plain args, NOT wrapped in
 * `LiveSizeSelectionCard`: there is nothing to select in this branch (it never reaches the
 * chip-click/keyboard-navigation code path at all), so the interactive wrapper would
 * misleadingly imply a selection state that cannot exist here — same reasoning
 * `WithSizeChipsOneSize` documents for itself.
 */
export const OneSize: Story = {
  args: {
    ...Default.args,
    sizeChipValues: [{ value: 'os', label: 'One size' }],
  },
};

/**
 * A variant re-fetch in progress: `isPriceLoading` forwards straight through to
 * ZimmProductCardContent → ZimmProductPrice, which renders its own invisible placeholder,
 * preserving the price's layout slot rather than collapsing it. See that atom's own docblock
 * and zimmProductCardContent's own `LoadingPrice` story for the mechanism.
 */
export const LoadingPrice: Story = {
  args: {
    ...Default.args,
    currentPrice: undefined,
    isPriceLoading: true,
  },
  render: (args) => <LiveSizeSelectionCard {...args} />,
};

